insert into public.questions(topic_id,kind,prompt,difficulty,presentation,solution,explanation,source_title,source_url,status,verified_at) select id,'who','Which Apollo astronaut was the first person to walk on the Moon?','easy','{"options":[{"id":"portrait-0","image":"/media/4f0bd2.jpg"},{"id":"portrait-1","image":"/media/8c81ee.jpg"},{"id":"portrait-2","image":"/media/0ab599.jpg"},{"id":"portrait-3","image":"/media/bdc394.jpg"}]}'::jsonb,'{"correct":"portrait-0","label":"Neil Armstrong","credits":[{"id":"portrait-0","subject":"Neil Armstrong","image":"/media/4f0bd2.jpg","license":"Public domain (NASA)","artist":"NASA","medium":"photograph","url":"https://images.nasa.gov/details/S69-31741","occupation":"astronaut","period":"Apollo program","region":"United States","birth":1930,"death":2012,"wikidata":"Q1615","field":"Human spaceflight"},{"id":"portrait-1","subject":"Buzz Aldrin","image":"/media/8c81ee.jpg","license":"Public domain (NASA)","artist":"NASA","medium":"photograph","url":"https://images.nasa.gov/details/S69-31743","occupation":"astronaut","period":"Apollo program","region":"United States","birth":1930,"death":null,"wikidata":"Q2252","field":"Human spaceflight"},{"id":"portrait-2","subject":"Michael Collins","image":"/media/0ab599.jpg","license":"Public domain (NASA)","artist":"NASA","medium":"photograph","url":"https://images.nasa.gov/details/S69-31742","occupation":"astronaut","period":"Apollo program","region":"United States","birth":1930,"death":2021,"wikidata":"Q104859","field":"Human spaceflight"},{"id":"portrait-3","subject":"Jim Lovell","image":"/media/bdc394.jpg","license":"Public domain (NASA)","artist":"NASA","medium":"photograph","url":"https://www.nasa.gov/former-astronaut-james-a-lovell/","occupation":"astronaut","period":"Apollo program","region":"United States","birth":1928,"death":2025,"wikidata":"Q111240","field":"Human spaceflight"}]}'::jsonb,'Neil Armstrong stepped onto the lunar surface first. Buzz Aldrin joined him there while Michael Collins remained in lunar orbit.','Apollo 11 mission','https://www.nasa.gov/mission/apollo-11/','published','2026-11-23T00:00:00Z'::timestamptz from public.topics where slug='apollo-11' on conflict do nothing;
insert into public.questions(topic_id,kind,prompt,difficulty,presentation,solution,explanation,source_title,source_url,status,verified_at) select id,'where','Where on Earth did Apollo 11 lift off from Launch Pad 39A?','standard','{}'::jsonb,'{"lat":28.608422,"lng":-80.604133,"scale":780,"label":"Kennedy Space Center, Florida"}'::jsonb,'Apollo 11 launched from the Kennedy Space Center on the Atlantic coast of Florida.','Apollo by the Numbers','https://www.nasa.gov/wp-content/uploads/2023/04/sp-4029.pdf','published','2026-11-23T00:00:00Z'::timestamptz from public.topics where slug='apollo-11' on conflict do nothing;
insert into public.questions(topic_id,kind,prompt,difficulty,presentation,solution,explanation,source_title,source_url,status,verified_at) select id,'when','In which year did the first crewed Moon landing take place?','standard','{"min":1900,"max":2020,"precision":"year"}'::jsonb,'{"min":1969,"max":1969,"precision":"year","scale":14,"label":"1969 CE"}'::jsonb,'The Apollo 11 lunar module landed in the Sea of Tranquility on July 20, 1969.','Apollo 11 mission data','https://nssdc.gsfc.nasa.gov/planetary/lunar/apollo11info.html','published','2026-11-23T00:00:00Z'::timestamptz from public.topics where slug='apollo-11' on conflict do nothing;
insert into public.questions(topic_id,kind,prompt,difficulty,presentation,solution,explanation,source_title,source_url,status,verified_at) select id,'what','Which spacecraft is shown in this photograph?','standard','{"options":[{"id":"option-1","label":"Eagle ascent stage"},{"id":"option-2","label":"Columbia command module"},{"id":"option-3","label":"Sputnik 1"},{"id":"option-4","label":"Voyager 1"}],"images":["/media/87af12.jpg","/media/3a7c50.jpg","/media/1e94b9.jpg","/media/62bef1.jpg"]}'::jsonb,'{"correct":"option-1","label":"Eagle ascent stage","credits":[{"license":"Public domain (NASA)","artist":"Michael Collins / NASA","url":"https://nssdc.gsfc.nasa.gov/imgcat/html/object_page/a11_h_44_6642.html"}]}'::jsonb,'Michael Collins photographed the upper stage of Eagle as it returned from the lunar surface to dock with Columbia.','Apollo 11 photo AS11-44-6642','https://nssdc.gsfc.nasa.gov/imgcat/html/object_page/a11_h_44_6642.html','published','2026-11-23T00:00:00Z'::timestamptz from public.topics where slug='apollo-11' on conflict do nothing;
insert into public.questions(topic_id,kind,prompt,difficulty,presentation,solution,explanation,source_title,source_url,status,verified_at) select id,'how','Put these Apollo 11 milestones in chronological order.','standard','{"options":[{"id":"option-1","label":"Launch from Florida"},{"id":"option-2","label":"Land in the Sea of Tranquility"},{"id":"option-3","label":"Dock Eagle ascent stage with Columbia"},{"id":"option-4","label":"Splash down on Earth"}]}'::jsonb,'{"correct":["option-1","option-2","option-3","option-4"],"label":"From launch to splashdown"}'::jsonb,'The crew reached lunar orbit before descending in Eagle. After the Moon walk, Eagle’s ascent stage took Armstrong and Aldrin back to Columbia for the journey home.','Apollo 11 mission overview','https://www.nasa.gov/mission/apollo-11/','published','2026-11-23T00:00:00Z'::timestamptz from public.topics where slug='apollo-11' on conflict do nothing;
insert into public.questions(topic_id,kind,prompt,difficulty,presentation,solution,explanation,source_title,source_url,status,verified_at) select id,'why','Choose the events that move sunlight through a raindrop to form a primary rainbow.','standard','{"mechanic":"evidence","options":[{"id":"option-1","label":"Sunlight bends when it enters a droplet."},{"id":"option-2","label":"Light reflects from the inside back surface."},{"id":"option-3","label":"Light bends again as it exits."},{"id":"option-4","label":"Wind changes the wavelength of the light."},{"id":"option-5","label":"The droplet emits its own visible light."}]}'::jsonb,'{"mechanic":"evidence","correct":["option-1","option-2","option-3"],"label":"Refraction, internal reflection, then refraction"}'::jsonb,'Light changes direction at each air–water boundary. Wavelengths bend by different amounts, which helps separate the colors.','How Do Rainbows Form?','https://www.weather.gov/fgz/Rainbow','published','2026-11-23T00:00:00Z'::timestamptz from public.topics where slug='rainbow' on conflict do nothing;
insert into public.questions(topic_id,kind,prompt,difficulty,presentation,solution,explanation,source_title,source_url,status,verified_at) select id,'how','Follow water from the ocean through a cloud and back to a river.','standard','{"options":[{"id":"option-1","label":"Ocean water evaporates"},{"id":"option-2","label":"Water vapor condenses into cloud droplets"},{"id":"option-3","label":"Rain falls to the ground"},{"id":"option-4","label":"Runoff enters a river"}]}'::jsonb,'{"correct":["option-1","option-2","option-3","option-4"],"label":"Evaporation, condensation, precipitation, runoff"}'::jsonb,'This is one possible route in the water cycle. Water may also soak into the ground or remain stored in snow and ice.','USGS Water Science School','https://water.usgs.gov/edu/watercycle-kids-beg.html','published','2026-11-23T00:00:00Z'::timestamptz from public.topics where slug='water-cycle' on conflict do nothing;
insert into public.questions(topic_id,kind,prompt,difficulty,presentation,solution,explanation,source_title,source_url,status,verified_at) select id,'why','Match each water-cycle observation with the process that explains it.','standard','{"mechanic":"matching","pairs":[{"id":"option-1","label":"A puddle shrinks on a warm day"},{"id":"option-2","label":"A cloud forms as moist air cools"},{"id":"option-3","label":"Water flows downhill after rain"}],"matches":[{"id":"run","label":"Surface runoff"},{"id":"evap","label":"Evaporation"},{"id":"cond","label":"Condensation"}]}'::jsonb,'{"mechanic":"matching","correct":{"option-1":"evap","option-2":"cond","option-3":"run"},"label":"Evaporation, condensation, and runoff"}'::jsonb,'Liquid water can become vapor by evaporation. Cooling turns some vapor back into droplets. Water that does not soak in can move over the surface.','USGS Water Science School','https://water.usgs.gov/edu/watercycle-kids-beg.html','published','2026-11-23T00:00:00Z'::timestamptz from public.topics where slug='water-cycle' on conflict do nothing;
