insert into public.questions(topic_id,kind,prompt,difficulty,presentation,solution,explanation,source_title,source_url,status,verified_at) select id,'how','Arrange this typical route for a federal bill that is signed into law.','standard','{"options":[{"id":"option-1","label":"Introduce the bill in one chamber"},{"id":"option-2","label":"The chamber passes the bill"},{"id":"option-3","label":"Both chambers approve identical text"},{"id":"option-4","label":"The President signs the bill"}]}'::jsonb,'{"correct":["option-1","option-2","option-3","option-4"],"label":"Introduction, passage, agreement, signature"}'::jsonb,'Both chambers must agree on identical text before it goes to the President. A veto override is a different route to enactment.','Congress.gov legislative process','https://www.congress.gov/legislative-process','published','2026-11-23T00:00:00Z'::timestamptz from public.topics where slug='us-legislation' on conflict do nothing;
